export const extraSpeakingLessonPart3 = indexExtras([
  ['Homework and independent learning', 'How can schools check whether a homework task was designed at a reasonable length?', 'They can ask pupils how long it actually took and compare experiences across the class. A teacher may estimate ten minutes while learners need an hour because a prerequisite was unclear. Feedback should be used to improve the task, not blame students for working at different speeds.'],
  ['Languages and cultural identity', 'Can a language remain alive mainly through formal lessons?', 'Lessons help provide vocabulary and confidence, but a language also needs ordinary reasons to use it. Friends, media and community activities create those opportunities. If students speak it only during an examination, they may know the rules without developing the relationships and habits that sustain everyday use.'],
  ['Changing career later in life', 'How can employers recognise useful experience from an unrelated career?', 'They can examine specific responsibilities rather than only compare job titles. A restaurant manager may have strong scheduling and conflict resolution skills useful elsewhere. A practical assessment can reveal those connections, while targeted training addresses gaps without requiring the applicant to repeat everything already learned.'],
  ['Public parks and urban heat', 'What should councils consider when choosing where to plant additional trees?', 'They need to look at heat exposure, available soil and the needs of people using the street. A tree that blocks an accessible path creates another problem. Maintenance and future growth also matter, so success should be measured by a healthy usable canopy rather than the number of seedlings planted.'],
  ['Older adults and digital services', 'Why can asking a relative to complete an online form be an inadequate solution?', 'It may require someone to reveal private health or financial information they would rather keep confidential. It also assumes that a reliable relative is available. Public services should offer appropriate assistance directly, allowing people to remain independent rather than make access to essential rights depend on their family relationships.'],
  ['Advertising and consumer choice', 'Should an advertisement explain significant limitations as clearly as its main promise?', 'Yes, otherwise a technically accurate statement can still produce a misleading impression. A cheap initial price may hide unavoidable charges later. Important conditions should be visible when the decision is made, not buried in a document that customers find only after responding to the attractive headline.'],
  ['Volunteer training and responsibility', 'How can organisations protect volunteers from taking on more work than they can sustain?', 'Roles should have clear hours and responsibilities, with a way to ask for support or step back. Enthusiasm can make someone agree to everything initially. Coordinators need to check the workload and arrange cover, rather than assume that commitment means a volunteer is always available without limits.'],
  ['Museums and public access', 'Can taking an exhibition outside a museum reach a different audience?', 'It can introduce material in a familiar place, such as a community centre, where some people feel more comfortable visiting. However, moving a few display boards is not enough if the explanation remains inaccessible. The exhibition should be developed with local partners and connect clearly with their interests.'],
  ['Libraries as community learning spaces', 'Why might a library need resources used by relatively few visitors?', 'A small language group or someone with a specialist access need may depend heavily on those resources. Popularity alone would overlook their importance. Libraries should consider demand and reasonable inclusion together, while cooperation between branches can provide less common materials without requiring every building to hold identical collections.'],
  ['Commercial influences on sport', 'Should a sports organisation disclose the conditions attached to sponsorship?', 'Yes, athletes and supporters should know whether funding influences event schedules, branding or other decisions. Disclosure allows people to judge the relationship rather than assume the support has no obligations. Some commercial details can remain private, but conditions affecting participants should not be hidden until they have already committed.'],
  ['Tourism in fragile environments', 'How can a visitor limit reflect conservation needs without becoming arbitrary?', 'Managers should explain the evidence behind the limit and review it as conditions change. A nesting season may require a temporary reduction that would not be necessary throughout the year. Clear booking arrangements and alternatives help visitors plan, making protection more credible than an unexplained number announced only at arrival.'],
  ['Reliability in public transport', 'Why is information about a disrupted journey almost as important as the timetable itself?', 'Passengers need to decide whether to wait, change routes or inform someone they will be late. An unexplained delay removes those choices. Accurate updates cannot repair the service, but they reduce uncertainty and prevent people from losing additional time because they keep relying on a departure that will not occur.'],
  ['Local food and shopping habits', 'Can a local food purchasing policy unintentionally exclude small growers?', 'Yes, a contract may require a volume or amount of paperwork that a small farm cannot manage. Dividing orders into suitable lots or working with a cooperative can help. Safety standards should remain, but the process should not favour only large distributors while claiming to support nearby producers.'],
  ['Flexible housing and changing households', 'Why should housing design allow spaces to serve more than one purpose?', 'Household needs change with work, age and family circumstances. A room that can become a study or a bedroom may let residents stay rather than move. Flexibility should not mean every space is compromised, though; daylight, storage and privacy still need to work when the arrangement changes.'],
  ['Childcare and working patterns', 'Why can predictable working hours matter as much as flexible hours for parents?', 'A parent needs to know when care must be arranged, and repeated last minute changes can make even a nominally flexible job difficult. Predictability allows planning with a provider or relative. Useful flexibility should give the worker some control, not merely allow the employer to vary hours whenever demand changes.'],
  ['Skills training and economic opportunity', 'What makes a training programme useful to people who already have substantial experience?', 'It should identify the actual gap and build on what learners can already do. Repeating basic material wastes time and may discourage attendance. Practical recognition, targeted modules and opportunities to apply new skills are more helpful than treating every participant as a beginner simply because they lack a particular certificate.'],
  ['Household renewable energy', 'Why should energy advice consider renters as well as homeowners?', 'Renters may pay the bills but lack authority to install equipment or improve insulation. Advice focused only on purchasing a system excludes them. Landlords, public incentives and tenancy rules therefore matter, while residents still need clear information about practical steps they can take without risking their housing or spending on unsuitable products.'],
  ['Ethics in scientific research', 'How can researchers make consent meaningful rather than merely obtain a signature?', 'Participants need to understand the purpose, likely demands and right to withdraw in language they can use. Time for questions is important, especially when people feel dependent on the institution. A signed form provides a record, but it does not prove understanding if the explanation was rushed or unnecessarily technical.'],
  ['New residents and local services', 'How can a community learn what newcomers need without making assumptions?', 'Services can consult people directly through several languages and accessible settings, rather than rely on one representative to speak for everybody. New residents have different skills and circumstances. Clear feedback about what can change also matters, because collecting needs without responding may weaken trust in the organisations asking the questions.'],
  ['Shared offices and flexible workspaces', 'What rules help protect confidential work in a shared office?', 'People need clear expectations about calls, screens and meeting rooms, because friendly surroundings do not remove professional privacy obligations. A quiet private room may be essential for some tasks. Providers should explain what is available before a booking, allowing workers to judge suitability rather than discover the limitation after joining.'],
  ['Automation in healthcare', 'Who should be accountable when automated advice contributes to a clinical error?', 'Responsibility needs to be defined across the provider, developer and professional using the system. Blaming the technology alone does not help a patient obtain an explanation. Services should record how recommendations were used and retain meaningful human review, while developers must be accountable for defects or misleading claims about capability.'],
  ['Remote education and classroom interaction', 'How can online teaching make room for learners who are reluctant to speak in a large group?', 'Small discussions, written questions and individual check ins offer different ways to contribute. The teacher should connect those contributions to the lesson rather than leave them in an unread chat. Participation is better judged by meaningful engagement than by how often a learner switches on a microphone in front of everyone.'],
  ['Historical memory and public monuments', 'Can explaining a disputed monument be more useful than either celebrating or hiding it?', 'Sometimes, because interpretation can show why it was erected and why its meaning is contested today. That helps people examine the evidence. But explanation is not automatically sufficient for every setting, particularly where the object still causes serious harm; communities should compare contextualisation, relocation and other options carefully.'],
  ['Public art and community decisions', 'Why should a public artwork include a plan for its future care?', 'Weather, lighting and everyday use can change how the work is experienced or make it unsafe. A care plan protects the original investment and identifies who will pay. Commissioning should include those costs from the start, rather than leave a later council to choose between expensive repairs and visible neglect.'],
  ['Music across generations and cultures', 'Can sharing the story behind a song help listeners appreciate unfamiliar music?', 'It can reveal why a rhythm, lyric or occasion matters to the people performing it. That creates a starting point without requiring immediate enjoyment of every style. The explanation should remain open to different interpretations, rather than tell listeners that understanding the background obliges them to like the music.'],
  ['Recipes and cultural identity', 'Should a traditional recipe be allowed to change when people move to a new country?', 'Certainly, ingredients, equipment and daily routines may be different, so adaptation can keep the dish in use. People can explain the original version while enjoying a variation. Treating one recipe as permanently fixed may turn a living tradition into a test of authenticity that excludes the families trying to maintain it.'],
  ['Sleep and modern working hours', 'Why is individual sleep advice sometimes insufficient for shift workers?', 'Their timetable may require wakefulness at times when rest would be natural, and changing it is not a personal choice. Predictable rotas and adequate recovery periods are therefore important. Advice about phones or caffeine can help at the margins, but it should not hide the employer’s responsibility for an unreasonable schedule.'],
  ['Public consultation and local decisions', 'What should authorities do after rejecting a recommendation from a consultation?', 'They should explain the evidence, constraints and reasons for the decision in a form participants can understand. Otherwise, people may feel their time was wasted. Consultation does not guarantee that every suggestion is accepted, but it should make a visible contribution and leave officials accountable for the choice they make.'],
  ['Consumer privacy and digital services', 'Why should people be able to withdraw permission for optional data collection?', 'Circumstances and preferences can change after someone joins a service, so an initial choice should not bind them indefinitely. Withdrawal must be practical and explained clearly. Information needed for a current contract may require different treatment, but optional tracking should not continue merely because leaving it on is profitable for the company.'],
  ['Product durability and repair', 'How could a product’s repairability be explained before purchase?', 'A clear label could identify available parts, ordinary repair costs and the period of support. Buyers would then compare future use as well as the immediate price. The claims need independent checks, because an attractive repair score means little if a crucial component cannot actually be obtained when it fails.'],
  ['Wild animals in urban neighbourhoods', 'How can waste management reduce conflict with urban wildlife?', 'Secure bins and reliable collection remove a predictable food source that draws animals close to people. The approach needs coordination across homes and businesses, because one overflowing area can undermine neighbouring efforts. It is more sustainable than repeatedly removing animals while leaving the same attractive conditions unchanged.'],
  ['Preparedness for natural disasters', 'Why should emergency plans include the period after residents reach a shelter?', 'Reaching safety is only the first step. People may need medication, accessible toilets, reliable updates or help contacting relatives. If these needs are ignored, some may leave the shelter too early. Planning for ordinary necessities makes evacuation more realistic and protects those who cannot independently arrange everything after arrival.'],
  ['Preventing food waste', 'Can better package sizes help households waste less food?', 'Yes, someone living alone may be forced to buy more than they can use before it spoils. Smaller portions or flexible quantities can address that problem. However, they should not always carry a large price penalty, or customers with little money will still choose the bigger package despite the likely waste.'],
  ['Fashion choices and textile waste', 'How can a repair service be made attractive to ordinary clothing buyers?', 'It needs clear prices and a straightforward way to leave and collect an item. People may repair a favourite coat if replacing a zip is predictable and affordable. Brands could support common repairs, but the service must offer genuine value rather than mainly bring customers into a shop to buy something new.'],
  ['Work organised through digital platforms', 'Why is a clear appeals process important when a platform suspends a worker?', 'Suspension can remove income immediately, even when the underlying complaint is mistaken or incomplete. Workers need to know the reason, provide evidence and receive a timely decision from someone able to review it. An automated message without that route gives the appearance of a process while leaving the person unable to challenge it.'],
  ['Public toilets and access to city life', 'How can opening hours affect the usefulness of a public toilet?', 'A well designed facility is useless to a passenger if it closes before evening buses finish. Hours should reflect local activity and known needs, with safety and cleaning planned accordingly. Publishing accurate information helps, but the priority is a usable service rather than a map listing a building that people repeatedly find locked.'],
  ['Water use during drought', 'Why should water suppliers report how much is lost through leakage?', 'It shows whether the organisation is addressing its own waste while asking households to conserve. Transparent reporting can build trust and direct investment towards repairs. Customers still have responsibilities, but restrictions feel less credible when substantial losses are hidden and ordinary users are presented as the only source of the problem.'],
  ['Protecting coastlines from erosion', 'Should coastal property buyers receive information about future protection costs?', 'Yes, they need to understand both the physical risk and whether continued defence is realistic. A sea view can distract from obligations that emerge later. Clear information supports an informed purchase and reduces the expectation that the public must fund indefinite protection of every new building in an exposed location.'],
  ['Security for tenants in rented homes', 'Why can delays in returning a deposit make moving especially difficult?', 'The household may need that money to secure another home, so a delay creates a barrier even when it has paid rent responsibly. Clear deadlines and evidence for deductions help. A fair dispute process should also be accessible, because a tenant facing an urgent move cannot easily wait months for an expensive legal solution.'],
  ['Responsible ownership of companion animals', 'How should families plan for a pet when their daily routine changes?', 'They need to consider who can provide exercise, food and care during longer absences. A new job does not remove the animal’s needs. Reliable arrangements or a suitable care service may help, but if the situation cannot work, seeking responsible rehoming early is better than leaving the animal neglected.'],
  ['Checking the reliability of news', 'Why does the date of a report matter when judging a shared story?', 'An old report may be accurate about its original event but misleading when presented as current news. Circumstances or evidence may have changed. Checking the date and source helps readers avoid reacting to a recycled claim, especially when the person sharing it has removed the context that would make its age clear.'],
  ['Online influence and spending decisions', 'Should a sponsored recommendation remain clearly labelled when it is shared again?', 'Yes, the commercial relationship still affects how viewers should interpret it, even if the clip appears on another account. Removing the label can make advertising look like independent enthusiasm. Platforms and creators should preserve that context rather than assume everyone saw the original post or knows who paid for the promotion.'],
  ['Resolving disputes between neighbours', 'Why should a complaint describe specific incidents rather than general character judgements?', 'Specific details give the other person something they can understand and change, such as music after a particular time. Calling someone inconsiderate invites an argument about personality instead. A clear record can also help mediation or formal reporting, while exaggeration and public accusations may make a manageable problem harder to resolve.'],
  ['Experience and qualifications in recruitment', 'How can recruitment tasks avoid becoming unpaid labour for the employer?', 'They should be brief, clearly connected to the skill being assessed and not produce substantial usable work for the company. Applicants need to know the purpose in advance. Where a task requires significant time or creates commercial value, payment is appropriate; an assessment should not become a convenient way to obtain free output.'],
  ['Families discussing money with children', 'Can children learn financial judgement without receiving regular pocket money?', 'Yes, they can help compare prices, plan a small family purchase or discuss why one option is chosen over another. These activities teach decisions without requiring every household to provide an allowance. Lessons should respect different budgets and avoid making a child feel less capable simply because they have less money to practise with.'],
  ['Priorities in ocean and space research', 'How can research fields cooperate even when they compete for funding?', 'They may share instruments, methods or data that answer related questions. Satellite observations can support ocean science, for example. Funding structures should recognise those connections rather than force each team to exaggerate differences. Cooperation still needs clear responsibility, so useful sharing does not leave essential maintenance or interpretation to an unspecified partner.'],
  ['Food labels and informed choices', 'Why should nutritional information describe realistic serving sizes?', 'A tiny serving can make a product’s figures look reassuring while most people consume much more at once. Clear amounts help buyers compare what they are actually likely to eat. Labels should present the whole package as well where useful, rather than use mathematically correct information to create an impractical impression.'],
  ['Street design and road safety', 'What can a temporary street redesign teach planners before a permanent project?', 'It can reveal how people move and whether a crossing or barrier creates an unexpected difficulty. Feedback from disabled users and nearby businesses is particularly useful. The trial must still be safe and monitored, but adjusting a temporary layout is easier than correcting an expensive permanent design after its problems become obvious.'],
  ['Keeping small towns economically viable', 'Why is a town’s success not captured simply by the number of newcomers?', 'Population growth may support shops while also raising rents or stretching services. Existing residents need to benefit, not merely watch the place become more expensive. Employment quality, housing access and reliable facilities give a fuller picture, allowing authorities to distinguish lasting improvement from a brief increase that creates other pressures.'],
  ['Preserving personal photographs and digital records', 'Why should a digital archive include explanations as well as images?', 'An image may remain technically intact while future viewers no longer know who appears or why the moment mattered. Names, dates and brief context preserve that meaning. Families should also consider privacy when adding sensitive information, so the archive helps later understanding without making every personal detail available to everyone.'],
  ['Weather information and everyday planning', 'How can forecasters explain uncertainty without making their information seem useless?', 'They can show the range of likely outcomes and connect it to practical choices. A chance of heavy rain may suggest carrying protection or preparing an alternative venue. Uncertainty does not mean there is no useful evidence; clear explanation helps people use the forecast without treating one symbol as a guarantee.'],
  ['Inclusive participation in school sport', 'Why should pupils have opportunities to restart an activity after a discouraging experience?', 'An early difficult lesson can make a child assume they are permanently bad at sport. A different activity or smaller goal may change that view. Teachers should offer supportive routes back without forcing public comparison, helping pupils recognise that confidence and skill can develop rather than treating one performance as a fixed identity.'],
  ['Fairness in examinations and grading', 'How can assessment recognise improvement without abandoning consistent standards?', 'The final judgement can still use clear criteria while feedback records what has developed over time. Students then understand both their current level and the next step. Improvement should not automatically replace evidence of competence, but acknowledging it can support learning rather than make the assessment feel like a permanent label.'],
  ['Accessible design for everyday products', 'Why should accessibility features be tested after a product is updated?', 'A software change or new component may alter controls that users previously relied on. An update described as an improvement can therefore introduce a barrier. Continued testing with different users protects practical access, rather than assume that a product remains suitable forever because its original design once met a standard.'],
  ['Film stories and cultural representation', 'Can one successful film make audiences overlook other voices from the same country?', 'Yes, its style and characters may become the familiar image that distributors expect again. That can limit access to different stories, even though the first film broadened attention. Supporting varied work and explaining that no single narrative represents a whole society helps keep international interest from becoming another narrow stereotype.'],
  ['Borrowing and consumer credit', 'Why should debt advice be independent of the lender selling a product?', 'A seller may benefit from recommending further borrowing, while the customer needs an assessment of what is genuinely manageable. Independent advice can compare options without that incentive. It should be confidential and accessible early, because waiting until several payments are missed makes the choices narrower and the stress greater.'],
]);

type MockExtra = [topic: string, part1Prompt: string, part1Answer: string, part3Prompt: string, part3Answer: string];
const mockRows: MockExtra[] = [
  ['A community space opened after a delay', 'Would good lighting make you more likely to visit a public space after dark?', 'Yes, especially if the route home were well lit too. I would enjoy a short evening visit, but an attractive square would not persuade me to walk through a place where I felt unsafe.', 'Why should planning a public space include the routes people use to reach it?', 'A pleasant destination may remain inaccessible if surrounding crossings or paths are unsafe. People experience the whole journey, not just the designed site. Planners should consult different users and connect the space to everyday routes, rather than assume that an attractive entrance will overcome barriers outside the project boundary.'],
  ['Advice for a first independent journey', 'Would you write down important travel details in case your phone stopped working?', 'I would keep the destination address and booking details somewhere else. My phone usually works well, but a small backup would let me ask for help without remembering everything during an unexpected problem.', 'How can travel advice support someone without removing their chance to learn?', 'It can explain major risks and useful resources while leaving ordinary choices to the traveller. Giving a young adult every step may reduce uncertainty but also prevent practice in solving manageable problems. The level of support should reflect experience and circumstances, rather than assume either complete control or complete independence is always best.'],
  ['A practical safety workshop', 'Do you find it useful to repeat a practical skill after the first lesson?', 'Yes, trying it again helps me remember the sequence and notice what I misunderstood. I would rather practise a safe task with feedback than assume I had mastered it after watching one demonstration.', 'Why might emergency skills need refresher training?', 'A rarely used procedure can be forgotten, and guidance or equipment may change. Brief supervised refreshers let people check their understanding before a real emergency. The training should build appropriate confidence and explain when professional help is necessary, not encourage participants to attempt risky action simply because they once completed a course.'],
  ['A public pool reopened for different users', 'Would you check how crowded a swimming session was before booking?', 'Yes, because I enjoy having enough room to swim steadily. A quiet session would suit me better than a busy one, even if I needed to adjust the time I usually exercised.', 'How does cleanliness affect access to a shared sports facility?', 'People may avoid a facility they cannot trust, even when fees and opening hours are suitable. Dependable cleaning and clear responsibility for faults are essential. Managers should respond to user reports and maintain changing areas as well as the main activity space, rather than judge quality only by the equipment provided.'],
  ['A trip with a smaller environmental footprint', 'Would you accept a slightly longer journey if it gave you a more pleasant route?', 'I would for a leisure trip with no urgent deadline. A route through a park or a quieter street can make travelling part of the enjoyment instead of something to finish as quickly as possible.', 'Why should sustainable travel options also be affordable?', 'People cannot consistently choose an option that exceeds their budget, even if they understand its environmental benefit. Reliable pricing and practical connections therefore matter alongside awareness campaigns. Authorities and operators should address those barriers rather than interpret every cheaper, higher impact choice as evidence that the traveller does not care.'],
  ['Learning to waste less food', 'Would you choose a smaller package if you were cooking only for yourself?', 'I would compare the amount I could realistically use. A larger package may look cheaper, but it is not a saving if half remains unused and I eventually have to throw it away.', 'How can consistent date labels help reduce food waste?', 'Clear distinctions between safety limits and quality guidance help people avoid discarding suitable food through confusion. Labels need understandable wording and appropriate storage advice. Education supports this, but businesses should use the same principles consistently so customers are not required to interpret a different system on every product they buy.'],
  ['Useful lessons from a temporary job', 'Would you keep a note of skills learned during a short period of work?', 'Yes, I might forget useful examples later when applying for another role. Recording how I handled a customer or learned a procedure would help me explain the experience more clearly in an interview.', 'How can employers recognise skills acquired during brief employment?', 'They can provide a clear record of responsibilities and specific feedback rather than only confirm dates. A short job may involve substantial learning, especially when tasks are varied. Recognition should be honest about the level reached, but it should not dismiss competence simply because the worker was not permanently employed.'],
  ['A documentary about an invisible city system', 'Would a programme make you look differently at something ordinary on your route?', 'It could. After an explanation of drainage, I started noticing where rainwater went near my street. The programme made familiar details interesting without needing me to travel somewhere unusual to see them.', 'How should an educational programme explain what experts still do not know?', 'It should make the uncertainty part of the explanation, showing which observations are reliable and where interpretation remains open. Viewers can handle a qualified answer if it is clear. Presenting a neat conclusion merely for dramatic effect may create confidence that the evidence does not support.'],
  ['Responding calmly to a weather warning', 'Would you tell a friend if a warning might affect plans you had made together?', 'Definitely. I would check the information first and suggest a safer alternative early, rather than leave them preparing for a trip we might cancel just before meeting.', 'Why should warnings be available through several communication channels?', 'A single app may miss people with limited connectivity, a flat battery or an unfamiliar language. Broadcasts, local services and clear public notices can reach different groups. The messages should remain consistent across those channels, otherwise greater coverage could produce confusion about which instruction is current and what action is actually required.'],
  ['A reading discussion with an unexpected viewpoint', 'Would you join a book discussion even if you had not finished the book?', 'I would ask whether that was acceptable and explain how far I had read. I could still listen and discuss the opening, although I would avoid a meeting if I strongly wanted to preserve the ending.', 'How can a discussion group make room for less confident readers?', 'A facilitator can invite contributions without forcing people to speak and avoid rewarding only detailed literary terminology. Short passages or advance questions offer a starting point. Participants should be able to ask about uncertainty, because a welcoming discussion depends on exploring ideas rather than demonstrating who has the most sophisticated vocabulary.'],
  ['Organising shared family responsibilities', 'Do you prefer being reminded of a task or setting your own reminder?', 'I prefer setting my own reminder once we have agreed the task. It helps me take responsibility, and it avoids making another family member spend time checking whether I have remembered.', 'Why should shared responsibilities include the work of planning and remembering?', 'Someone can perform several visible tasks while another person carries the continual burden of scheduling and checking everything. Ignoring that work makes the division seem fairer than it is. Families can assign complete responsibilities where practical, while discussing different capacities rather than demand identical contributions from everyone.'],
  ['Making a toy from discarded packaging', 'Would you enjoy a craft activity without knowing exactly what the finished object would look like?', 'Yes, if the materials were easy to work with. Discovering the result as I went along would feel more playful than trying to copy a perfect example and worrying about every small difference.', 'What should adults check before children use discarded materials for play?', 'They need to consider sharp edges, small detachable pieces and whether the material is clean and suitable for the child’s age. Reuse does not automatically make an object safe. Once these boundaries are addressed, children can make creative choices without the adult controlling every detail of what they produce.'],
  ['A modest outdoor musical performance', 'Would you stay to hear an unfamiliar performer if the first song interested you?', 'Probably, especially at a small event where I could listen comfortably. I like discovering someone unexpectedly, and one interesting song would encourage me to hear how the rest of their music sounded.', 'How can an event distinguish fair opportunities for beginners from unpaid exploitation?', 'The organiser should explain the terms, costs and expected benefit honestly. A genuinely voluntary learning opportunity differs from using performers to generate revenue while refusing payment. Beginners still contribute time and skill, so transparent arrangements and reasonable expenses are important even when the event is modest.'],
  ['A budget that made an unexpected expense manageable', 'Do you prefer checking your spending briefly and often or doing a detailed review occasionally?', 'Brief regular checks suit me better because I can remember what the purchases were for. A long review after several months would feel harder, especially if I had forgotten many small transactions.', 'Why should budgeting advice recognise irregular income?', 'A plan based on identical monthly earnings may fail a worker paid seasonally or by task. They need to consider uncertain periods and essential commitments differently. Advice should reflect that reality and available support, rather than suggest that one neat spreadsheet proves every household can save the same amount each month.'],
  ['A tree that became part of a local decision', 'Would you notice if a familiar tree were absent from your daily route?', 'Yes, especially one that provided shade where I usually stopped. Its absence would change how the street felt, and I would wonder whether it had been removed for safety or for another reason.', 'Why should tree planting plans include care over several years?', 'Young trees need appropriate watering, soil and protection before they provide the expected canopy. Counting planting events without survival can exaggerate success. Authorities should budget for care and choose suitable locations, so the community receives lasting shade and ecological value rather than repeated photographs of seedlings that later disappear.'],
  ['Feedback that made a presentation clearer', 'Would you ask a listener to tell you which part of an explanation was confusing?', 'Yes, a specific question would help more than simply asking whether the presentation was good. I could then revise the unclear section instead of trying to change everything based on a vague reaction.', 'How can differences in authority affect the honesty of feedback?', 'A junior employee may hesitate to challenge a manager even when the explanation is unclear. Leaders can invite specific criticism and demonstrate that it does not lead to punishment. Anonymous routes may help, but trust ultimately depends on what happens when someone raises an inconvenient concern openly.'],
  ['Recording a family story with permission', 'Would you ask a storyteller to check your notes before sharing them?', 'I would, especially if the story included something personal. They might want to correct a detail or keep part private, and checking would show that recording the conversation did not give me control over it.', 'Should permission to record a personal story automatically allow public sharing?', 'No, those are different decisions. Someone may be happy to preserve a memory for family members but not want strangers to hear it. Consent should specify the audience and allow discussion of later changes, especially when the account includes information about other people who were not part of the original conversation.'],
  ['A shared home with better personal space', 'Would you use headphones at home to avoid disturbing someone nearby?', 'For music or a video, yes. It is a simple way to share a small room more comfortably, although I would still ask about calls or other sounds that headphones cannot prevent.', 'How can a household balance shared space with changing needs for privacy?', 'Members can agree which activities need quiet and how spaces are used at different times. A room does not have to be permanently private to provide useful privacy. Clear routines and occasional review help, because arrangements that worked before remote work or a new family member may no longer fit everyone.'],
  ['Learning a few words for a new neighbour', 'Would you write down a useful expression after someone taught it to you?', 'Yes, otherwise I might remember the sound only briefly. I would note when to use it and try it again later, so learning the phrase became part of an actual conversation.', 'How can beginners show respect without pretending to speak a language fluently?', 'They can use a few expressions carefully, listen and admit when they do not understand. The effort can make contact warmer, but guessing in an important conversation may create problems. Willingness to learn should be combined with appropriate translation or assistance when accurate information matters.'],
  ['A shop that made ordering easier', 'Would a shop’s patient explanation encourage you to return?', 'Yes, particularly when I was buying something unfamiliar. A clear answer without pressure would make me feel comfortable asking again, whereas an impatient reaction could discourage me even if the prices were good.', 'Why should a shop test an ordering system with occasional customers?', 'Regular users may know shortcuts that a newcomer cannot see. Testing with occasional customers reveals unclear steps and assumptions, including accessibility problems. A service should not require a customer to become an expert simply to make a basic purchase, and feedback must lead to changes rather than only confirm the designer’s preference.'],
  ['Borrowing tools from a neighbourhood library', 'Would you check a borrowed item’s condition before taking it home?', 'Yes, so I knew how it worked and could point out any existing damage. That would protect both me and the lending scheme, especially if the item were unfamiliar or had several parts.', 'How can a sharing scheme avoid excluding people through high deposits?', 'It can use proportionate deposits, membership support or other safeguards rather than assume everyone can leave a large sum temporarily. Equipment still needs protection, but high barriers may exclude the residents who benefit most from borrowing. Clear responsibility and dependable records can reduce risk without making access depend mainly on income.'],
  ['Finding a suitable place for focused study', 'Do you find it easier to begin studying when your materials are already arranged?', 'I do. Having the right book and notes ready removes small excuses to delay, and I can spend the first few minutes understanding the task rather than looking for things.', 'How can a college allocate limited quiet study spaces fairly?', 'It could combine reservable places with some available for immediate use and review whether demand differs by time. Rules should prevent long unused bookings. Students with particular access needs may require suitable arrangements, so fairness means practical opportunity to study rather than applying an identical procedure regardless of circumstances.'],
  ['A visit to a working farm', 'Would you want to know which season was best before visiting a farm?', 'Yes, because the activities and conditions would be different across the year. I would rather choose a time when visitors were welcome than arrive during demanding work and expect somebody to show me around.', 'Why should farm visits explain normal work rather than only show attractive activities?', 'Visitors may otherwise develop an unrealistic picture of food production. Weather, maintenance and difficult decisions are part of farming too. A clear explanation can include those realities without overwhelming guests, helping consumers understand the effort behind a product rather than leave with only photographs of animals and picturesque fields.'],
  ['Making an announcement easier to understand', 'Would you ask someone unfamiliar with an event to read a notice before you displayed it?', 'I would, because they might spot missing details I had taken for granted. A quick check of the place, time and contact information could prevent many repeated questions later.', 'How can organisations prevent several conflicting versions of a notice from circulating?', 'They should identify the current version, date updates clearly and remove outdated copies where possible. A single contact or official page can help users verify details. Responsibility for maintenance needs to be assigned, because clear writing loses its value if people cannot tell whether the information is still accurate.'],
  ['Trying an adult dance class', 'Would comfortable clothing matter more than appearance in a beginner activity class?', 'For me it would. I would want to move easily and focus on the lesson, rather than keep adjusting an outfit chosen mainly to look good in a photograph.', 'How can a recreational class accommodate participants with different physical limits?', 'The instructor can offer suitable variations and avoid treating one movement as the only valid way to participate. Participants should be able to explain concerns privately. Inclusion still requires attention to safety, so modifications need informed judgement rather than encourage everybody to attempt the same activity regardless of pain or medical advice.'],
  ['Watching a craft worker demonstrate printing', 'Would seeing the making process change how you valued an ordinary object?', 'It probably would. Watching someone carefully align a print would make me notice the work behind it, and I might appreciate small differences I had previously mistaken for simple imperfections.', 'Should craftspeople be paid when teaching through public demonstrations?', 'Where the event relies on their skill to attract visitors, payment is usually appropriate. Preparing, explaining and supervising take time away from production. A maker may choose an occasional promotional demonstration, but organisers should not assume cultural value or exposure removes the need for fair compensation.'],
  ['A map that revealed an old route', 'Would you compare a historical map with the streets visible today?', 'Yes, I would enjoy finding a route or boundary that still survived. The comparison would make the old map easier to understand and might change how I noticed an otherwise ordinary part of town.', 'Why should a historical claim be checked against more than one kind of record?', 'Each source was produced for a purpose and may leave important details out. A map shows layout, while personal accounts or records can explain how people used the place. Comparing evidence helps identify uncertainty rather than treat one attractive source as a complete and unquestionable history.'],
  ['A trial of more flexible working hours', 'Would a clear end time help you separate work from the rest of your day?', 'Yes, even with a flexible start I would want a reasonable finishing point. Otherwise, I might keep answering small requests and feel that the whole evening remained partly reserved for work.', 'Why might flexible teams still need some agreed contact hours?', 'Shared hours can make coordination possible without requiring everyone to follow an identical day. The period should be limited to genuine needs rather than recreate a full fixed schedule. Teams can review it as work changes, ensuring that flexibility remains practical for both individual responsibilities and tasks requiring collaboration.'],
  ['A repaired toy kept for its meaning', 'Would you keep a photograph of an object you could no longer store?', 'I might, especially if the memory mattered more than using the object again. A photograph with a short note would let me remember it without needing to keep every possession indefinitely.', 'How can restoration preserve meaning without removing every sign of use?', 'A repair can stabilise an object while retaining marks that record its history. The owner’s purpose should guide the decision, because a cherished toy may not need to look new. A skilled repairer can explain options and risks rather than assume that a flawless surface is always the most valuable result.'],
  ['A neighbourhood mural made with residents', 'Would you like an explanation of who contributed to a community artwork?', 'Yes, knowing the people and ideas behind it would make the image more interesting. I might recognise a detail differently after hearing why a resident wanted it included in the design.', 'Why should a community art project explain ownership and maintenance before work begins?', 'Residents and artists may have different expectations about future changes, repairs or removal. Clear agreements prevent a later dispute from damaging the relationships the project created. Public involvement is valuable, but enthusiasm at the painting stage does not automatically establish who will fund care or decide what happens if the wall’s use changes.'],
  ['A personal letter worth waiting for', 'Would you reread a message more often if it contained a thoughtful personal detail?', 'Yes, a detail showing that someone remembered our conversation would make it feel special. I might save that message even if it were short, because the attention would matter more than the length.', 'How should privacy affect the preservation of personal correspondence?', 'Letters may contain information about people who never agreed to become part of an archive. Preservation can still be valuable, but access may need limits or a delay. Families and institutions should consider consent and context rather than assume that possessing a message gives unlimited permission to publish it.'],
  ['Learning from an unsuccessful prototype', 'Would you photograph different stages of a practical project?', 'I would if the stages helped explain what changed. Keeping a few images could show why one approach failed and save me from repeating it when I returned to the idea later.', 'When should a team stop testing an idea that repeatedly fails?', 'It should consider whether new evidence or a changed method makes another attempt informative. Repetition without learning can waste time, especially when risks or costs are rising. Clear stopping criteria and outside feedback help distinguish persistence from defending an idea mainly because the team has already invested effort in it.'],
  ['An old cinema given a new purpose', 'Would information about a building’s former use make a visit more interesting?', 'Yes, especially if I could still see a feature from that period. A short explanation would connect the present space with the people who used it before, rather than leave the old details unexplained.', 'How can a conversion make a historic building accessible without disguising its past?', 'Designers can identify significant features and introduce necessary access through carefully planned changes. Clear interpretation helps visitors understand what was retained and what is new. Accessibility should not be dismissed as a threat to heritage, because a building preserved for public value offers less of that value if many people cannot enter it.'],
  ['Completing a difficult local walk together', 'Would you agree on a way to stop a shared activity if someone became uncomfortable?', 'I would before setting out. Knowing that we could turn back without embarrassment would make the walk more enjoyable, and it would stop a personal goal becoming pressure on somebody else.', 'Why should shared goals allow participants to revise the plan?', 'People’s health, circumstances or understanding of the challenge may change. A flexible agreement lets the group respond without treating adjustment as betrayal. The purpose of a shared goal should include the participants’ wellbeing, rather than place an original target above every later piece of evidence about what is realistic or safe.'],
  ['A useful disagreement before buying a camera', 'Would trying a product in a shop matter more than reading another review?', 'For something I needed to hold and operate, yes. Reviews could explain the features, but trying the controls myself would show whether it felt comfortable and suited the way I intended to use it.', 'How can a buyer judge advice from someone who earns money from the sale?', 'The advice may still be knowledgeable, but the incentive should be recognised. Buyers can ask specific questions, compare independent information and check the return terms. A trustworthy seller explains limitations as well as benefits, rather than present every costly feature as necessary for the customer’s actual use.'],
  ['A conversation that clarified a decision about moving', 'Would you spend an ordinary day in a new area before deciding to live there?', 'I would if possible. Visiting a shop, travelling at a busy time and walking the likely route home would teach me more about daily life than seeing only an attractive street on a quiet afternoon.', 'How can a listener help with a major decision without imposing their own preference?', 'They can ask what matters most to the person, clarify trade offs and point out assumptions that need checking. Giving an opinion is sometimes useful, but it should be identified as advice rather than the only reasonable answer. The final choice depends on circumstances the listener may not fully understand.'],
];

export const extraSpeakingMockInterviews: Record<string, { part1: SpeakingQuestionResponse; part3: SpeakingQuestionResponse }> = {};
for (const [topic, part1Prompt, part1Answer, part3Prompt, part3Answer] of mockRows) {
  if (extraSpeakingMockInterviews[topic]) throw new Error(`Repeated extra Speaking mock topic: ${topic}`);
  extraSpeakingMockInterviews[topic] = {
    part1: { prompt: part1Prompt, answer: part1Answer },
    part3: { prompt: part3Prompt, answer: part3Answer },
  };
}
